def countSubIslands(grid1: list[list[int]], grid2: list[list[int]]) -> int:
    R, C = len(grid1), len(grid1[0])
    def dfs(r, c):
        if r < 0 or r >= R or c < 0 or c >= C or grid2[r][c] == 0:
            return True
        grid2[r][c] = 0
        is_sub = (grid1[r][c] == 1)
        d1 = dfs(r + 1, c)
        d2 = dfs(r - 1, c)
        d3 = dfs(r, c + 1)
        d4 = dfs(r, c - 1)
        return is_sub and d1 and d2 and d3 and d4
    ans = 0
    for r in range(R):
        for c in range(C):
            if grid2[r][c] == 1:
                if dfs(r, c): ans += 1
    return ans

